+int blapi_system_get_rootfs_len(char boot_flag)
+{
+	int fd = -1;
+	ssize_t read_size;
+	unsigned int data = 0;
+	int rootfs_len = 0;
+	char kernel_dev[16] = {0};
+
+	blapi_system_get_partition_dev(boot_flag, kernel_dev, sizeof(kernel_dev), NULL, 0);
+
+	if((fd = open(kernel_dev, O_RDONLY)) == -1)
+	{
+		ecnt_blapi_printf("open file %s fail\n", kernel_dev);
+		return -1;
+	}
+
+	if(lseek(fd, IMAGE_SPLIT_OFFSET - 8, SEEK_SET) == (off_t) - 1)
+	{
+		ecnt_blapi_printf("seek in %s fail\n", kernel_dev);
+		close(fd);
+		return -1;
+	}
+
+	read_size = read(fd, &data, sizeof(data));
+	if(read_size != sizeof(data))
+	{
+		ecnt_blapi_printf("fail -- only read %zd\n", read_size);
+		close(fd);
+		return -1;
+	}
+
+	rootfs_len = (int)htonl(data);
+
+	close(fd);
+	return rootfs_len;
+}
